Ltac ph1_apply6c vSR vsn vDR vdn vswpl vdwpl vsy vdy vsph vdph vdh DS4 DD4 DDST LOR DSH :=
  ph_norm2 DD4 DS4; gnorm;
  reg_val (Z_to_bv 5 23) ltac:(fun vs7 => reg_val (Z_to_bv 5 1) ltac:(fun vra =>
  lazymatch vs7 with Z_to_bv 64 ?vPS => lazymatch vra with Z_to_bv 64 ?vPD =>
  frame_fact ltac:(fun FR =>
  let FR0 := fresh "FR0" in let FC16 := fresh "FC16" in let FC40 := fresh "FC40" in let FC120 := fresh "FC120" in
  sub_at FR 0 1%nat FR0; sub_at FR 16 1%nat FC16; sub_at FR 40 6%nat FC40; sub_at FR 120 4%nat FC120; rewrite ?Z.add_0_r in FR0;
  lazymatch type of FC16 with rw_cells _ _ _ [C8 (Z_to_bv 64 ?vfs4)] =>
  lazymatch type of FC40 with rw_cells _ _ _ (C8 (Z_to_bv 64 ?vhh) :: C8 (Z_to_bv 64 ?vSY) :: C8 (Z_to_bv 64 ?vsy0) :: _ :: C8 (Z_to_bv 64 ?vdy0) :: _) =>
  let PS4 := fresh "PS4" in let PD4 := fresh "PD4" in
  let SDH := fresh "SDH" in let DDH := fresh "DDH" in let RS := fresh "RS" in let RSN := fresh "RSN" in let RS2 := fresh "RS2" in let RD := fresh "RD" in
  assert (PS4 : vPS mod 4 = 0) by (clear - DS4; Z.div_mod_to_equations; lia);
  assert (PD4 : vPD mod 4 = 0) by (clear - DD4; Z.div_mod_to_equations; lia);
  assert (SDH : vswpl * vdh <= 2^24) by (assert (vswpl * vdh <= vswpl * vsph) by (apply Z.mul_le_mono_nonneg_l; lia); lia);
  assert (DDH : vdwpl * vdh <= 2^24) by (assert (vdwpl * vdh <= vdwpl * vdph) by (apply Z.mul_le_mono_nonneg_l; lia); lia);
  assert (RS : forall i', 0 <= i' < vdh -> vSR <= vPS + 4 * (vswpl * i') /\ vPS + 4 * (vswpl * i') + 4 <= vSR + vsn)
    by (apply (rows_fit' vSR vsn vPS vswpl vdh 4 vsy vsph); lia);
  assert (RSN : forall i', 0 <= i' <= vdh -> vSR <= vPS + 4 * (vswpl * i') /\ vPS + 4 * (vswpl * i') + 4 <= vSR + vsn + 4 * vswpl)
    by (intros i' Hi'; assert (vswpl * (vsy + i') <= vswpl * vsph) by (apply Z.mul_le_mono_nonneg_l; lia); assert (0 <= vswpl * i') by (apply Z.mul_nonneg_nonneg; lia);
        assert (0 <= vswpl * vsy) by (apply Z.mul_nonneg_nonneg; lia); lia);
  assert (RS2 : forall fs9, fs9 = 1 -> vfs4 = 0 -> forall i', 0 <= i' < vdh -> vPS + 4 * (vswpl * i') + 8 <= vSR + vsn)
    by (intros fs9' E9 E4; first [ exfalso; clear - E4; lia | intros i' Hi'; apply (proj2 ((rows_fit' vSR vsn vPS vswpl vdh 8 vsy vsph ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia)) i' Hi')) ]);
  assert (RD : forall i', 0 <= i' < vdh -> vDR <= vPD + 4 * (vdwpl * i') /\ vPD + 4 * (vdwpl * i') + 4 <= vDR + vdn)
    by (apply (rows_fit' vDR vdn vPD vdwpl vdh 4 vdy vdph); lia);
  eapply evt_cut; [ eapply g3f1_fullc with (SR := vSR) (sn := vsn) (DR := vDR) (dn := vdn) (PS1 := vPS) (PD1 := vPD) (fs4 := vfs4)
                               (dh := vdh) (swpl := vswpl) (dwpl := vdwpl) (dy := vdy0) (dpixh := vdph) (sy := vsy0) (spixh := vsph) (SY := vSY) (hangh := vhh);
      first [exact FR0 | exact FC16 | exact FC40 | exact FC120 | exact RS | exact RSN | exact (RS2 _) | exact RD | exact SDH | exact DDH
            | assumption | (unfold hid in DSH; exact DSH) | reflexivity | (unfold hidq in *; assumption) | lia | (unfold hid in DDST; clear - DDST LOR; lia) | (unfold hid in *; lia) ] | ];
  cbv beta; intros ?ms' (?f_ra & ?f_t0 & ?f_t2 & ?f_t3 & ?f_t4 & ?f_a0 & ?f_a1 & ?f_a2 & ?f_a3 & ?f_a5 & ?f_a7 & ?f_s3 & ?f_s4 & ?f_s5 & ?f_s6 & ?f_s7 & ?f_s8 & ?f_s9 & ?f_s11 & ?mf & -> & ?MU' & ?WM' & ?MIf);
  gphase_post2 DSH DDST LOR; try clear FR0; try clear FC16; try clear FC40; try clear FC120; try clear RS; try clear RSN; try clear RS2; try clear RD; try clear SDH; try clear DDH; try clear PS4; try clear PD4; ropl_rehide
  end end) end end)).

