  pw6 [0x137ce0; 0x137e74];
  (first [ at_pc 0x137ce0; ph2_apply6c vSR vsn vDR vdn vswpl vdwpl vSY vDY vsph vdph vDH DS4 DD4 DDST LOR DSH | idtac ]);
  ph_norm2 DD4 DS4;
  last_flag ltac:(fun w => lazymatch w with
    | Z_to_bv 64 0 => cell_split 8; ph3_apply6c vSR vsn vDR vdn vswpl vdwpl vSY vDY vsph vdph vDH DS4 DD4 DDST LOR DSH
    | _ => pw6 [0x13a27c] end);
  unfold hid in *; ropl_leave EXIT m0 lo usp.


